quiz.code:
#include <stdio.h>

struct Student {
    int roll;
    char name[20];
    int mark;
};

int main(void)
{
    struct Student student = {.roll = 17, .name = "Learner", .mark = 82};
    printf("%d %s %d\n", student.roll, student.name, student.mark);
    return 0;
}

#include <stdio.h>

struct Student {
    int roll;
    char name[20];
    int mark;
};

int main(void)
{
    struct Student first = {11, "Alpha", 65};
    struct Student second = first;
    second.roll = 12;
    second.name[0] = 'O';
    second.mark = 90;
    printf("%s %d | %s %d\n", first.name, first.mark, second.name, second.mark);
    return 0;
}

#include <stdio.h>

struct Student {
    int roll;
    char name[20];
    int mark;
};

int main(void)
{
    struct Student student = {.roll = 23};
    printf("%d %d %d\n", student.roll, student.mark, student.name[0] == '\0');
    student.mark = 75;
    printf("Updated: %d\n", student.mark);
    return 0;
}

